L=/home/usain/gov-os-worktrees/W1-42/.gov-runtime/scratch/lead/log; python3 /home/usain/gov-os-worktrees/W1-42/.gov-runtime/scratch/lead/sumcheck.py $L/check-a-r8.json > $L/check-a-r8.summary.txt; python3 - $L/check-a-r8.json <<'EOF'
import json,sys
d=json.load(open(sys.argv[1]))
r=(d.get('error') or {}).get('details') or d.get('result')
for c in r['checks']:
    if c['status']!='GREEN' and c['id'] in ('core-schema','core-claims','recovery-rebuild','index-freshness','core-context-repro','context-reproducibility'):
        for f in c['findings']:
            print(c['id'], f.get('code'), (f.get('message') or '')[:160], f.get('path',''))
print([c['id'] for c in r['checks'] if 'context' in c['id']], [(c['id'],c['status']) for c in r['checks'] if 'context' in c['id']])
EOF
